"""specs_s200036.py - Sonnet-w2 family M (generated by mkfamM.py). 0x48c4b0 fills the first 0x60 bytes of the stack-local L; 0x4cc1d0 returns [L]; the engine slot 0x60 stub (5 stack args) and the
float slot 0x90 stub of the object (3 stack args, returns 1.5 on the x87 stack that the original pops) record their arguments; 0x4cbec0 reads L back; the /GS check is a recorder
preserving eax. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S, F
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    sr1, sr2, sr3, sr4 = seh_record(c, 2), seh_record(c, 2), seh_record(c, 2), seh_record(c, 2)

    def fill(emu, k):
        emu.wbytes(emu.arg32(0), bytes(r.getrandbits(8) for _ in range(0x60)))
        sr1(emu, k)

    def slot_side(emu, k):
        emu.calllog.append(('arg', tuple(emu.arg32(i) for i in range(5))))
        sr2(emu, k)

    def fslot_side(emu, k):
        emu.calllog.append(('farg', tuple(emu.arg32(i) for i in range(3))))
        sr4(emu, k)

    def dtor_side(emu, k):
        a = emu.reg('ecx')
        emu.calllog.append(('L', emu.rbytes(a, 16).hex()))
        sr3(emu, k)
    hook_rec(c, 0x48c4b0, 2, ret=r.getrandbits(32), pop=8, stackmark=(0,), side=fill)
    hook_rec(c, 0x4cc1d0, 0, ret=lambda emu, k: emu.r32(emu.reg('ecx')), this='mark')
    hook_rec(c, 0x4cbec0, 0, ret=r.getrandbits(32), this='mark', side=dtor_side)
    hook_rec(c, 0x633654, 0, ret=lambda emu, k: emu.reg('eax'), pop=0, this=True)
    g = obj(c, 0x40, {0x60: pystub(c, 5, ret=r.getrandbits(32), this=True, side=slot_side)}, nslots=0x30)
    c.emu.w32(0x700394, g)
    me = obj(c, 0x40, {0x90: pystub(c, 3, ret=r.getrandbits(32), this=True, side=fslot_side, st0=1.5)}, nslots=0x50)
    return [me, r.getrandbits(32), r.getrandbits(32)]


S(0x48ffd0, 'GUESS famM 0x48ffd0', 'thiscall', None, ret='eax', gen=_gen, note='batch200036')
S(0x4903b0, 'GUESS famM 0x4903b0', 'thiscall', None, ret='eax', gen=_gen, note='batch200036')
S(0x490500, 'GUESS famM 0x490500', 'thiscall', None, ret='eax', gen=_gen, note='batch200036')
S(0x490d20, 'GUESS famM 0x490d20', 'thiscall', None, ret='eax', gen=_gen, note='batch200036')
S(0x490ff0, 'GUESS famM 0x490ff0', 'thiscall', None, ret='eax', gen=_gen, note='batch200036')
